export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const g = inputs.gravity;
  const mass = inputs.mass;
  const apexTime = launchSpeed / g;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * g);
  const tMax = (2 * launchSpeed) / g;
  const tCurrent = Math.min(time, tMax);
  const v = launchSpeed - g * tCurrent;
  const height = launchSpeed * tCurrent - 0.5 * g * tCurrent * tCurrent;
  const a = -g;
  const F = mass * g;
  let motionState = 'Ready to toss';
  if (tCurrent > 0 && Math.abs(tCurrent - apexTime) > 0.02) {
    if (tCurrent < apexTime) {
      motionState = 'Rising';
    } else if (tCurrent < tMax) {
      motionState = 'Falling';
    } else {
      motionState = 'Back at launch height';
    }
  } else if (Math.abs(tCurrent - apexTime) <= 0.02) {
    motionState = 'At the top';
  }
  const objects = [];
  const leftLane = sdk.panel({
    x: 20,
    y: 35,
    w: 280,
    h: 360,
    title: 'The motion',
    state: motionState,
    id: 'lane.motion'
  });
  objects.push(...leftLane);
  const yAxis = sdk.axis('axis.height', {
    x: 80,
    y: 360,
    length: 290,
    orientation: 'y',
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: 'Height',
    unit: 'm'
  });
  objects.push(yAxis);
  const ballPixelY = 360 - (height / 2.2) * 290;
  const ballX = 140;
  const ball = sdk.circle('ball.toss', ballX, ballPixelY, 24);
  objects.push(ball);
  const vVec = sdk.vector('vec.v', { x: ballX + 25, y: ballPixelY }, {
    value: v,
    direction: 'up',
    scale: 15,
    minLength: 12,
    label: 'v'
  });
  objects.push(...vVec);
  const aVec = sdk.vector('vec.a', { x: ballX - 25, y: ballPixelY }, {
    value: a,
    direction: 'up',
    scale: 15,
    minLength: 12,
    label: 'a'
  });
  objects.push(...aVec);
  const calloutLines = [
    `v = ${sdk.format(v, 2)} m/s`,
    `a = ${sdk.format(a, 1)} m/s²`,
    `Fg = ${sdk.format(F, 1)} N`
  ];
  const calloutObj = sdk.callout(ballX + 45, ballPixelY - 30, calloutLines, { id: 'callout.toss' });
  objects.push(...calloutObj);
  const rightLane = sdk.panel({
    x: 320,
    y: 35,
    w: 300,
    h: 360,
    title: 'Velocity over time',
    state: `a = -${sdk.format(g, 1)} m/s²`,
    id: 'lane.vt'
  });
  objects.push(...rightLane);
  const plotPoints = [];
  const numPoints = 20;
  for (let i = 0; i <= numPoints; i++) {
    const ptTime = (tMax * i) / numPoints;
    const ptV = launchSpeed - g * ptTime;
    plotPoints.push({ x: ptTime, y: ptV });
  }
  const vtPlot = sdk.plot('plot.vt', {
    x: 330,
    y: 65,
    w: 280,
    h: 310,
    axes: {
      x: { label: 'Time', min: 0, max: 1.8, unit: 's' },
      y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' }
    },
    series: [
      { label: 'v(t)', kind: 'line', points: plotPoints }
    ]
  });
  objects.push(vtPlot);
  const quantities = {
    launchSpeed,
    gravity: g,
    mass,
    apexTime,
    apexHeight,
    height,
    velocity: v,
    acceleration: a,
    force: F
  };
  const readouts = [
    { id: 'velocity', value: v },
    { id: 'acceleration', value: a },
    { id: 'force', value: F },
    { id: 'motionState', value: motionState }
  ];
  return {
    frame: sdk.frame(objects, { width: 640, height: 420, readouts }),
    quantities
  };
}
